#!/bin/sh
# Review generated Podman commands before running this file.
set -eu
podman 'network' 'create' 'backend'
podman 'volume' 'create' 'alloy-data'
podman 'volume' 'create' 'grafana-data'
podman 'volume' 'create' 'loki-data'
podman 'volume' 'create' 'prometheus-data'
podman 'volume' 'create' 'telemetry-logs'
podman 'image' 'pull' '--policy=missing' 'docker.io/grafana/alloy@sha256:b8ec653c44235fbe910879145dac3597d66b0aaecf60bcbbe82580767771a839'
podman 'image' 'pull' '--policy=missing' 'docker.io/grafana/grafana@sha256:f772d434e8fab0049deb2b1b30abd43342bcfca1537614aa8d36080232cf4283'
podman 'image' 'pull' '--policy=missing' 'docker.io/library/nginx@sha256:42a516af16b852e33b7682d5ef8acbd5d13fe08fecadc7ed98605ba5e3b26ab8'
podman 'image' 'pull' '--policy=missing' 'docker.io/grafana/loki@sha256:d70e4659623f3e109af669cae76fe2a5dd5be54e2298fe8aed380d982fbc2500'
podman 'image' 'pull' '--policy=missing' 'docker.io/library/nginx@sha256:42a516af16b852e33b7682d5ef8acbd5d13fe08fecadc7ed98605ba5e3b26ab8'
podman 'image' 'pull' '--policy=missing' 'docker.io/prom/prometheus@sha256:5ce7540c3c00ef4ab0c9d2c995c6a5b9c421f44b4a115d97a2c7af3b1c21cbb0'
podman 'container' 'create' '--name' 'alloy' '--pull=never' '--network' 'backend' '--volume' 'alloy-data:/var/lib/alloy/data:rw,copy' '--volume' 'telemetry-logs:/var/log/boxferry:ro,copy' 'docker.io/grafana/alloy@sha256:b8ec653c44235fbe910879145dac3597d66b0aaecf60bcbbe82580767771a839' 'run' '--storage.path=/var/lib/alloy/data' '/etc/alloy/config.alloy'
podman 'container' 'create' '--name' 'grafana' '--pull=never' '--network' 'backend' '--volume' 'grafana-data:/var/lib/grafana:rw,copy' 'docker.io/grafana/grafana@sha256:f772d434e8fab0049deb2b1b30abd43342bcfca1537614aa8d36080232cf4283'
podman 'container' 'create' '--name' 'log-producer' '--pull=never' '--network' 'backend' '--volume' 'telemetry-logs:/var/log/boxferry:rw,copy' 'docker.io/library/nginx@sha256:42a516af16b852e33b7682d5ef8acbd5d13fe08fecadc7ed98605ba5e3b26ab8' 'sleep' '86400'
podman 'container' 'create' '--name' 'loki' '--pull=never' '--network' 'backend' '--volume' 'loki-data:/loki:rw,copy' 'docker.io/grafana/loki@sha256:d70e4659623f3e109af669cae76fe2a5dd5be54e2298fe8aed380d982fbc2500' '-config.file=/etc/loki/local-config.yaml'
podman 'container' 'create' '--name' 'metrics-producer' '--pull=never' '--network' 'backend' 'docker.io/library/nginx@sha256:42a516af16b852e33b7682d5ef8acbd5d13fe08fecadc7ed98605ba5e3b26ab8' 'sleep' '86400'
podman 'container' 'create' '--name' 'prometheus' '--pull=never' '--network' 'backend' '--volume' 'prometheus-data:/prometheus:rw,copy' 'docker.io/prom/prometheus@sha256:5ce7540c3c00ef4ab0c9d2c995c6a5b9c421f44b4a115d97a2c7af3b1c21cbb0' '--config.file=/etc/prometheus/prometheus.yml' '--storage.tsdb.path=/prometheus' '--storage.tsdb.retention.time=24h' '--web.enable-remote-write-receiver'
podman 'container' 'start' 'alloy'
podman 'container' 'start' 'grafana'
podman 'container' 'start' 'log-producer'
podman 'container' 'start' 'loki'
podman 'container' 'start' 'metrics-producer'
podman 'container' 'start' 'prometheus'
